-- Entrenamientos y tokens del conector MCP: equivalente en Postgres/Supabase de la migración EF "AddWorkouts".
-- Es idempotente: se puede volver a ejecutar sin duplicar nada.

create table if not exists "WorkoutSessions" (
  "Id" integer generated by default as identity primary key,
  "UserId" integer not null,
  "Title" varchar(200) not null,
  "Date" timestamp not null,
  "Notes" text null,
  "Completed" boolean not null default false,
  "Source" varchar(50) null,
  "ExternalId" varchar(200) null,
  "ExercisesJson" text not null default '[]',
  "UpdatedAt" timestamp not null
);
create index if not exists "IX_WorkoutSessions_UserId_Date" on "WorkoutSessions" ("UserId", "Date");
create index if not exists "IX_WorkoutSessions_UserId_Source_ExternalId" on "WorkoutSessions" ("UserId", "Source", "ExternalId");

create table if not exists "ApiTokens" (
  "Id" integer generated by default as identity primary key,
  "UserId" integer not null,
  "Name" varchar(100) not null,
  "TokenHash" varchar(64) not null,
  "Prefix" varchar(12) not null,
  "CreatedAt" timestamp not null,
  "LastUsedAt" timestamp null
);
create unique index if not exists "IX_ApiTokens_TokenHash" on "ApiTokens" ("TokenHash");

-- Como el resto de tablas: RLS activado y sin políticas, de modo que la API REST de Supabase (clave anónima) no ve nada.
-- La API de Compás se conecta con un rol propietario y no se ve afectada.
alter table "WorkoutSessions" enable row level security;
alter table "ApiTokens" enable row level security;
